// Общие шаги для тестов «New Job с техником → Create Job → автоматический SMS технику» (#8ae966, #8feef0).
// @writes: создаётся работа (клиент QA-quota client, описание «QA-AUTO …»), в конце — статус Cancelled.
// Техник — ТОЛЬКО «QA-F5 tech» (вымышленный +15555550100, согласие на SMS ON). Никогда Sofia Marin / Kirill.
// Запрос functions/v1/send-sms ПЕРЕХВАТЫВАЕТСЯ: тело запоминается ДО ответа, ответ — фейковый 422 recipient_invalid.
// Реальный запрос к серверу SMS (Twilio) не уходит никогда (route.continue не вызывается).
// Не сверено с сайтом при записи (правило проекта — не открывать сайт): разметка контейнера toast
// (ищем ближайший [data-sonner-toast] / li / role=status|alert), формат тела send-sms (ищем строку «Job:» во всех строковых полях),
// реакция приложения на фейковый ответ (заголовок toast «The SMS to QA-F5 tech …» — по скриншотам 18.10).
import { expect, Page, Request } from '@playwright/test';
import { openNewJob, openDispatch, pickTechnician } from '../dispatch-sms/dispatch-helpers';
import { setJobStatus } from '../job-closed-date/closed-helpers';

export { startInTest, restoreTest } from '../multi-business/business-helpers';

/** Единственный разрешённый техник: вымышленный номер, Twilio его отклоняет. */
export const QA_TECH = { name: 'QA-F5 tech', phoneDigits: '5555550100', phoneE164: '+15555550100' } as const;
/** Клиент из тестовых данных компании «test» (адрес подставляется сам). */
export const QA_CLIENT = 'QA-quota client';

export type SmsCall = { url: string; method: string; body: string };

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
};

/**
 * Перехват send-sms: каждый POST запоминается (url + тело) и получает фейковый ответ 422 recipient_invalid
 * (так отвечает сервер на вымышленный номер). Наружу запрос не уходит.
 */
export async function fakeSmsRejected(page: Page): Promise<SmsCall[]> {
  const calls: SmsCall[] = [];
  await page.route(/send-?sms/i, async (route) => {
    const req: Request = route.request();
    if (req.method() === 'OPTIONS') {
      await route.fulfill({ status: 204, headers: CORS, body: '' });
      return;
    }
    calls.push({ url: req.url(), method: req.method(), body: req.postData() ?? '' });
    await route.fulfill({
      status: 422,
      headers: { ...CORS, 'content-type': 'application/json' },
      body: JSON.stringify({ ok: false, error: 'recipient_invalid', code: 'recipient_invalid' }),
    });
  });
  return calls;
}

/** Каждый перехваченный SMS адресован только QA-F5 tech (страховка от реального техника). */
export function expectOnlyQaTech(calls: SmsCall[]) {
  for (const c of calls) {
    expect(c.body.replace(/\D/g, ''), `send-sms только на ${QA_TECH.phoneE164}, тело: ${c.body.slice(0, 300)}`).toContain(QA_TECH.phoneDigits);
  }
}

/** Все строковые значения JSON-тела (рекурсивно); если тело не JSON — само тело. */
export function bodyStrings(body: string): string[] {
  const out: string[] = [];
  const walk = (v: unknown) => {
    if (typeof v === 'string') out.push(v);
    else if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') Object.values(v as Record<string, unknown>).forEach(walk);
  };
  try { walk(JSON.parse(body)); } catch { out.push(body); }
  return out;
}

/** Текст SMS из тела запроса — строковое поле, в котором есть строка «Job: …». */
export function smsText(call: SmsCall): string {
  const text = bodyStrings(call.body).find((s) => /^Job:/m.test(s));
  expect(text, `в теле send-sms нет текста со строкой «Job:» — тело: ${call.body.slice(0, 500)}`).toBeTruthy();
  return text as string;
}

/**
 * New Job (EN) → клиент QA-quota client → тип Repair → описание → Dispatch → QA-F5 tech → Create Job.
 * Возвращает URL созданной работы (для очистки) и её код JOB-XXXX.
 */
export async function createJobWithQaTech(page: Page, description: string): Promise<{ jobUrl: string; jobCode: string }> {
  expect(description.startsWith('QA-AUTO'), 'данные теста — с префиксом QA-AUTO').toBe(true);
  await openNewJob(page, 'en');
  const client = page.getByLabel('Client Name *');
  await client.pressSequentially('QA-quota', { delay: 20 });
  await page.getByRole('button').filter({ hasText: QA_CLIENT }).first().click();
  await expect(client).toHaveValue(QA_CLIENT);
  await expect(page.getByRole('textbox', { name: /^Address/ })).not.toHaveValue('');
  await page.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
  await page.getByRole('option', { name: 'Repair', exact: true }).click();
  await page.getByLabel('Job Description').fill(description);

  const panel = await openDispatch(page, 'en');
  await pickTechnician(page, panel, 'en', QA_TECH.name);
  await expect(panel).toContainText(new RegExp(`Recipients?:[\\s\\S]*${QA_TECH.name}`));

  await page.getByRole('button', { name: 'Create Job', exact: true }).click();
  await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
  const jobUrl = page.url().replace(/&tab=items/, '');
  const codeText = await page.getByText(/^#JOB-\d{4}$/).first().innerText({ timeout: 30_000 });
  return { jobUrl, jobCode: codeText.trim().replace(/^#/, '') };
}

/** Очистка: работа → Cancelled (удаления работ в интерфейсе нет). Перехват send-sms должен быть ещё активен. */
export async function cancelJob(page: Page, jobUrl: string) {
  if (!jobUrl || page.isClosed()) return;
  await page.goto(jobUrl);
  await setJobStatus(page, 'Cancelled');
}

export type ToastGeometry = {
  green: { top: number; bottom: number; left: number; right: number };
  sms: { top: number; bottom: number; left: number; right: number };
  overlap: boolean;
  gap: number;
  greenOnTop: boolean;
  smsOnTop: boolean;
};

/**
 * Геометрия двух toast: прямоугольники контейнеров, пересечение, зазор по вертикали,
 * и «читаемость» — элемент в центре заголовка каждого toast принадлежит этому toast (его ничем не накрыло).
 */
export async function toastGeometry(page: Page, greenTitle: RegExp | string, smsTitle: RegExp): Promise<ToastGeometry> {
  const g = await page.getByText(greenTitle).first().elementHandle();
  const s = await page.getByText(smsTitle).first().elementHandle();
  return page.evaluate(([gEl, sEl]) => {
    const box = (el: Element) => (el.closest('[data-sonner-toast], li, [role="status"], [role="alert"]') ?? el.parentElement ?? el) as HTMLElement;
    const gBox = box(gEl as Element);
    const sBox = box(sEl as Element);
    const gr = gBox.getBoundingClientRect();
    const sr = sBox.getBoundingClientRect();
    const xOverlap = Math.min(gr.right, sr.right) - Math.max(gr.left, sr.left);
    const yOverlap = Math.min(gr.bottom, sr.bottom) - Math.max(gr.top, sr.top);
    const onTop = (title: Element, container: HTMLElement) => {
      const r = title.getBoundingClientRect();
      const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      return !!hit && container.contains(hit);
    };
    const pick = (r: DOMRect) => ({ top: r.top, bottom: r.bottom, left: r.left, right: r.right });
    return {
      green: pick(gr),
      sms: pick(sr),
      overlap: xOverlap > 0 && yOverlap > 0,
      gap: gr.top >= sr.bottom ? gr.top - sr.bottom : sr.top - gr.bottom,
      greenOnTop: onTop(gEl as Element, gBox),
      smsOnTop: onTop(sEl as Element, sBox),
    };
  }, [g, s] as const);
}
